-- Rollback-only fixtures: optional material setup, stock isolation, payments and replay.
begin;
do $test$
declare shop uuid; e jsonb := $event${"id":"f7df9571-6c5e-452c-9966-0637e59da403","kind":"checkout.completed","data":{"id":"f7df9571-6c5e-452c-9966-0637e59da403","customerId":"c4d13b47-761b-416d-92bf-b0d9ce03d98a","newCustomer":null,"customerSnapshot":{"id":"c4d13b47-761b-416d-92bf-b0d9ce03d98a","name":"Customer","phone":"080111","address":""},"jobBalances":[{"id":"bc574a84-0198-4b8d-847d-dc2d9c539d35","description":"Two sheets","service":"Printing","amount":20000,"paidBefore":0,"paidThisCheckout":20000,"outstandingAfter":0},{"id":"d618b0c9-63a0-4207-bdaf-a9122151804c","description":"Customer caps","service":"Cap pressing","amount":250000,"paidBefore":0,"paidThisCheckout":30000,"outstandingAfter":220000}],"jobs":[{"id":"bc574a84-0198-4b8d-847d-dc2d9c539d35","serviceId":"401f3a2b-c59a-474c-91c3-7b2b66b045c9","description":"Two sheets","quantity":2,"source":"In shop / USB","width":null,"height":null,"amount":20000,"unitPrice":10000,"service":"Printing","materialId":"df6e60dc-0887-4706-972c-86616e7a833b","materialNeeded":2,"measurementUnit":"sheet","requireSize":false,"serviceVersion":1,"sourceNote":"","customerId":"c4d13b47-761b-416d-92bf-b0d9ce03d98a","createdAt":"2026-10-07T21:44:56.849Z","checkoutId":"f7df9571-6c5e-452c-9966-0637e59da403","checkoutPosition":0,"productionStatus":"Added","version":1,"createdBy":"df2bb1e7-2dd9-480c-b566-98e59343d6c9","createdByLabel":"Owner","modifiedBy":"df2bb1e7-2dd9-480c-b566-98e59343d6c9","modifiedByLabel":"Owner","modifiedAt":"2026-10-07T21:44:56.849Z"},{"id":"d618b0c9-63a0-4207-bdaf-a9122151804c","serviceId":"c2c924e3-e5da-4c8a-bcb6-d856256928b3","description":"Customer caps","quantity":5,"source":"In shop / USB","width":null,"height":null,"amount":250000,"unitPrice":50000,"service":"Cap pressing","materialId":null,"materialNeeded":0,"measurementUnit":"item","requireSize":false,"serviceVersion":1,"sourceNote":"","customerId":"c4d13b47-761b-416d-92bf-b0d9ce03d98a","createdAt":"2026-10-07T21:44:56.849Z","checkoutId":"f7df9571-6c5e-452c-9966-0637e59da403","checkoutPosition":1,"productionStatus":"Added","version":1,"createdBy":"df2bb1e7-2dd9-480c-b566-98e59343d6c9","createdByLabel":"Owner","modifiedBy":"df2bb1e7-2dd9-480c-b566-98e59343d6c9","modifiedByLabel":"Owner","modifiedAt":"2026-10-07T21:44:56.849Z"}],"expectedAccount":"wallet=0;","cashReceived":50000,"useWallet":false,"override":null,"method":"Cash","paidOn":"2026-10-07","reference":"","createdBy":"df2bb1e7-2dd9-480c-b566-98e59343d6c9","createdByLabel":"Owner","createdAt":"2026-10-07T21:44:56.849Z","total":270000,"allocations":[{"jobId":"bc574a84-0198-4b8d-847d-dc2d9c539d35","amount":20000},{"jobId":"d618b0c9-63a0-4207-bdaf-a9122151804c","amount":30000}],"allocated":50000,"walletUsed":0,"walletAdded":0,"walletAfter":0,"outstandingBefore":270000,"outstandingAfter":220000}}$event$::jsonb; rejected boolean;
begin
insert into auth.users(id,email,raw_user_meta_data,created_at) values('df2bb1e7-2dd9-480c-b566-98e59343d6c9','df2bb1e7-2dd9-480c-b566-98e59343d6c9@example.invalid','{}',now());
perform set_config('request.jwt.claim.sub','df2bb1e7-2dd9-480c-b566-98e59343d6c9',true);
shop:=public.create_shop('Materialless service test');
perform public.apply_service_event(shop,$event${"id":"97955b60-4528-4a98-a933-7bdb1deede96","kind":"service.created","data":{"id":"c2c924e3-e5da-4c8a-bcb6-d856256928b3","description":"Cap pressing","materialId":null,"price":50000,"modifiedBy":"df2bb1e7-2dd9-480c-b566-98e59343d6c9"}}$event$::jsonb);
if not exists(select 1 from public.services where id='c2c924e3-e5da-4c8a-bcb6-d856256928b3' and material_id is null) then raise exception 'Materialless creation failed';end if;
perform public.apply_customer_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','customer.created','data',jsonb_build_object('id','c4d13b47-761b-416d-92bf-b0d9ce03d98a','name','Customer','phone','080111','address','','creditLimit',0,'modifiedBy','df2bb1e7-2dd9-480c-b566-98e59343d6c9')));
perform public.apply_material_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','material.created','data',jsonb_build_object('id','df6e60dc-0887-4706-972c-86616e7a833b','name','Paper','available',10,'measurementUnit','sheet','requireSize',false,'modifiedBy','df2bb1e7-2dd9-480c-b566-98e59343d6c9')));
perform public.apply_service_event(shop,jsonb_build_object('id',gen_random_uuid(),'kind','service.created','data',jsonb_build_object('id','401f3a2b-c59a-474c-91c3-7b2b66b045c9','description','Printing','materialId','df6e60dc-0887-4706-972c-86616e7a833b','price',10000,'modifiedBy','df2bb1e7-2dd9-480c-b566-98e59343d6c9')));
-- Link then unlink, retaining audit and not changing stock.
perform public.apply_service_event(shop,$event${"id":"dfa34f7d-14e6-44b6-a1dd-67b01989eafa","kind":"service.updated","data":{"id":"c2c924e3-e5da-4c8a-bcb6-d856256928b3","description":"Cap pressing","materialId":"df6e60dc-0887-4706-972c-86616e7a833b","price":50000,"baseVersion":1,"modifiedBy":"df2bb1e7-2dd9-480c-b566-98e59343d6c9"}}$event$::jsonb);
perform public.apply_service_event(shop,$event${"id":"482deec9-448c-4fe0-a41d-68bd81a56950","kind":"service.updated","data":{"id":"c2c924e3-e5da-4c8a-bcb6-d856256928b3","description":"Cap pressing","materialId":null,"price":50000,"baseVersion":2,"modifiedBy":"df2bb1e7-2dd9-480c-b566-98e59343d6c9"}}$event$::jsonb);
e:=jsonb_set(e,'{data,jobs,1,serviceVersion}','3');
rejected:=false;
begin perform public.apply_checkout_event(shop,jsonb_set(e,'{data,jobs,1,materialNeeded}','1')); exception when others then rejected:=true;end;
if not rejected then raise exception 'Forged stock usage accepted';end if;
if exists(select 1 from public.jobs where shop_id=shop) or (select available from public.materials where id='df6e60dc-0887-4706-972c-86616e7a833b')<>10 then raise exception 'Rejected checkout partially applied';end if;
perform public.apply_checkout_event(shop,e);
perform public.apply_checkout_event(shop,e);
if (select available from public.materials where id='df6e60dc-0887-4706-972c-86616e7a833b')<>8 or (select version from public.materials where id='df6e60dc-0887-4706-972c-86616e7a833b')<>2 then raise exception 'Mixed checkout stock incorrect';end if;
if (select count(*) from public.material_stock_changes where shop_id=shop)<>2 then raise exception 'Materialless job created a stock history record';end if;
if (select count(*) from public.jobs where shop_id=shop)<>2 then raise exception 'Mixed checkout or retry failed';end if;
if not exists(select 1 from public.jobs where id='d618b0c9-63a0-4207-bdaf-a9122151804c' and amount=250000 and metadata->'materialId'='null'::jsonb and metadata->>'materialNeeded'='0') then raise exception 'Materialless job snapshot incorrect';end if;
if not exists(select 1 from public.checkout_records where id='f7df9571-6c5e-452c-9966-0637e59da403' and (data->>'total')::bigint=270000 and (data->>'outstandingAfter')::bigint=220000) then raise exception 'Receipt amount incorrect';end if;
if (select sum(amount) from public.payment_allocations where shop_id=shop)<>50000 then raise exception 'Job payment allocation incorrect';end if;
end $test$;
rollback;
